// NULL-tolerant scan buffer for accountScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type accountPreloadBuf struct {
	ID          sql.Null[uuid.UUID]
	HouseholdID sql.Null[uuid.UUID]
	PoolID      sql.Null[uuid.UUID]
	Name        sql.Null[string]
	Kind        sql.Null[string]
	CreatedAt   sql.Null[time.Time]
	CardLast4   sql.Null[string]
}

// accountScanMapperNullable maps the preloaded account
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func accountScanMapperNullable(prefix string) scan.Mapper[*Account] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*Account, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *accountPreloadBuf) any
		}
		targets := make([]target, 0, 7)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *accountPreloadBuf) any { return &b.ID }})
			case "household_id":
				targets = append(targets, target{i, func(b *accountPreloadBuf) any { return &b.HouseholdID }})
			case "pool_id":
				targets = append(targets, target{i, func(b *accountPreloadBuf) any { return &b.PoolID }})
			case "name":
				targets = append(targets, target{i, func(b *accountPreloadBuf) any { return &b.Name }})
			case "kind":
				targets = append(targets, target{i, func(b *accountPreloadBuf) any { return &b.Kind }})
			case "created_at":
				targets = append(targets, target{i, func(b *accountPreloadBuf) any { return &b.CreatedAt }})
			case "card_last4":
				targets = append(targets, target{i, func(b *accountPreloadBuf) any { return &b.CardLast4 }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(accountPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*Account, error) {
				buf := link.(*accountPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.Valid) &&
					!(buf.HouseholdID.Valid) &&
					!(buf.PoolID.Valid) &&
					!(buf.Name.Valid) &&
					!(buf.Kind.Valid) &&
					!(buf.CreatedAt.Valid) &&
					!(buf.CardLast4.Valid) {
					return nil, nil
				}

				o := new(Account)
				if buf.ID.Valid {
					o.ID = buf.ID.V
				}
				if buf.HouseholdID.Valid {
					o.HouseholdID = buf.HouseholdID.V
				}
				o.PoolID = buf.PoolID
				if buf.Name.Valid {
					o.Name = buf.Name.V
				}
				if buf.Kind.Valid {
					o.Kind = buf.Kind.V
				}
				if buf.CreatedAt.Valid {
					o.CreatedAt = buf.CreatedAt.V
				}
				o.CardLast4 = buf.CardLast4
				return o, nil
			}
	}
}

func (o *Account) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "AccountIncomes":
		rels, ok := retrieved.(AccountIncomeSlice)
		if !ok {
			return fmt.Errorf("account cannot load %T as %q", retrieved, name)
		}

		o.R.AccountIncomes = rels
		o.R.Loaded.AccountIncomes = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Account = o
				rel.R.Loaded.Account = true
			}
		}
		return nil
	case "Household":
		rel, ok := retrieved.(*Household)
		if !ok {
			return fmt.Errorf("account cannot load %T as %q", retrieved, name)
		}

		o.R.Household = rel
		o.R.Loaded.Household = true

		if rel != nil {
			rel.R.Accounts = AccountSlice{o}
		}
		return nil
	case "Pool":
		rel, ok := retrieved.(*Pool)
		if !ok {
			return fmt.Errorf("account cannot load %T as %q", retrieved, name)
		}

		o.R.Pool = rel
		o.R.Loaded.Pool = true

		if rel != nil {
			rel.R.Accounts = AccountSlice{o}
		}
		return nil
	case "CorrectionPayments":
		rels, ok := retrieved.(CorrectionPaymentSlice)
		if !ok {
			return fmt.Errorf("account cannot load %T as %q", retrieved, name)
		}

		o.R.CorrectionPayments = rels
		o.R.Loaded.CorrectionPayments = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Account = o
				rel.R.Loaded.Account = true
			}
		}
		return nil
	case "PurchasePayments":
		rels, ok := retrieved.(PurchasePaymentSlice)
		if !ok {
			return fmt.Errorf("account cannot load %T as %q", retrieved, name)
		}

		o.R.PurchasePayments = rels
		o.R.Loaded.PurchasePayments = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Account = o
				rel.R.Loaded.Account = true
			}
		}
		return nil
	case "Purchases":
		rels, ok := retrieved.(PurchaseSlice)
		if !ok {
			return fmt.Errorf("account cannot load %T as %q", retrieved, name)
		}

		o.R.Purchases = rels
		o.R.Loaded.Purchases = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Account = o
				rel.R.Loaded.Account = true
			}
		}
		return nil
	case "RecurringExpenses":
		rels, ok := retrieved.(RecurringExpenseSlice)
		if !ok {
			return fmt.Errorf("account cannot load %T as %q", retrieved, name)
		}

		o.R.RecurringExpenses = rels
		o.R.Loaded.RecurringExpenses = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Account = o
				rel.R.Loaded.Account = true
			}
		}
		return nil
	case "Transfers":
		rels, ok := retrieved.(TransferSlice)
		if !ok {
			return fmt.Errorf("account cannot load %T as %q", retrieved, name)
		}

		o.R.Transfers = rels
		o.R.Loaded.Transfers = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Account = o
				rel.R.Loaded.Account = true
			}
		}
		return nil
	default:
		return fmt.Errorf("account has no relationship %q", name)
	}
}

type accountPreloader struct {
	Household func(...psql.PreloadOption) psql.Preloader
	Pool      func(...psql.PreloadOption) psql.Preloader
}

func buildAccountPreloader() accountPreloader {
	return accountPreloader{
		Household: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Household, HouseholdSlice](psql.PreloadRel{
				Name: "Household",
				Sides: []psql.PreloadSide{
					{
						From:        Accounts,
						To:          Households,
						FromColumns: []string{"household_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Households.Columns.Names(), householdScanMapperNullable, opts...)
		},
		Pool: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Pool, PoolSlice](psql.PreloadRel{
				Name: "Pool",
				Sides: []psql.PreloadSide{
					{
						From:        Accounts,
						To:          Pools,
						FromColumns: []string{"household_id", "pool_id"},
						ToColumns:   []string{"household_id", "id"},
					},
				},
			}, Pools.Columns.Names(), poolScanMapperNullable, opts...)
		},
	}
}

