type accountJoins[Q dialect.Joinable] struct {
	typ                string
	AccountIncomes     modAs[Q, accountIncomeColumns]
	Household          modAs[Q, householdColumns]
	Pool               modAs[Q, poolColumns]
	CorrectionPayments modAs[Q, correctionPaymentColumns]
	PurchasePayments   modAs[Q, purchasePaymentColumns]
	Purchases          modAs[Q, purchaseColumns]
	RecurringExpenses  modAs[Q, recurringExpenseColumns]
	Transfers          modAs[Q, transferColumns]
}

func (j accountJoins[Q]) aliasedAs(alias string) accountJoins[Q] {
	return buildAccountJoins[Q](buildAccountColumns(alias), j.typ)
}

func buildAccountJoins[Q dialect.Joinable](cols accountColumns, typ string) accountJoins[Q] {
	return accountJoins[Q]{
		typ: typ,
		AccountIncomes: modAs[Q, accountIncomeColumns]{
			c: AccountIncomes.Columns,
			f: func(to accountIncomeColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, AccountIncomes.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.AccountID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		Household: modAs[Q, householdColumns]{
			c: Households.Columns,
			f: func(to householdColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Households.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.HouseholdID),
					))
				}

				return mods
			},
		},
		Pool: modAs[Q, poolColumns]{
			c: Pools.Columns,
			f: func(to poolColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Pools.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.ID.EQ(cols.PoolID),
					))
				}

				return mods
			},
		},
		CorrectionPayments: modAs[Q, correctionPaymentColumns]{
			c: CorrectionPayments.Columns,
			f: func(to correctionPaymentColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, CorrectionPayments.NameExpr().As(to.Alias())).On(
						to.AccountID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		PurchasePayments: modAs[Q, purchasePaymentColumns]{
			c: PurchasePayments.Columns,
			f: func(to purchasePaymentColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, PurchasePayments.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.AccountID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		Purchases: modAs[Q, purchaseColumns]{
			c: Purchases.Columns,
			f: func(to purchaseColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Purchases.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.PaymentAccountID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		RecurringExpenses: modAs[Q, recurringExpenseColumns]{
			c: RecurringExpenses.Columns,
			f: func(to recurringExpenseColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, RecurringExpenses.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.PaymentAccountID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		Transfers: modAs[Q, transferColumns]{
			c: Transfers.Columns,
			f: func(to transferColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Transfers.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.PaymentAccountID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
